function lucideDefinition(svg) {
  const name = svg.match(/\blucide-([a-z0-9-]+)"/)?.[1];
  const nodes = svg.match(/<svg[^>]*>([\s\S]*?)<\/svg>/)?.[1].trim().replace(/<([a-z][\w:-]*)([^>]*?)\s*\/>/g, "<$1$2></$1>");
  if (!name || !nodes) throw new Error("invalid_lucide_icon");
  return { name, nodes };
}
